function mergeProfiles(accounts: string[][]): string[][] {
  const adj = new Map<string, string[]>(), owner = new Map<string, string>();
  const link = (a: string, b: string) => {
    if (!adj.has(a)) adj.set(a, []);
    if (!adj.has(b)) adj.set(b, []);
    adj.get(a)!.push(b);
    adj.get(b)!.push(a);
  };
  for (const [name, ...emails] of accounts) {
    for (const e of emails) { owner.set(e, name); link(emails[0], e); }
  }
  const seen = new Set<string>(), out: string[][] = [];
  for (const startEmail of adj.keys()) {
    if (seen.has(startEmail)) continue;
    seen.add(startEmail);
    const group: string[] = [], stack = [startEmail];
    while (stack.length) {
      const e = stack.pop()!;
      group.push(e);
      for (const nb of adj.get(e)!) if (!seen.has(nb)) { seen.add(nb); stack.push(nb); }
    }
    group.sort();
    out.push([owner.get(startEmail)!, ...group]);
  }
  return out;
}

