    def mergeProfiles(self, accounts: List[List[str]]) -> List[List[str]]:
        adj = defaultdict(list)
        owner = {}
        for name, *emails in accounts:
            for e in emails:
                owner[e] = name
                adj[emails[0]].append(e)
                adj[e].append(emails[0])
        seen, out = set(), []
        for start in adj:
            if start in seen:
                continue
            seen.add(start)
            group, stack = [], [start]
            while stack:
                e = stack.pop()
                group.append(e)
                for nb in adj[e]:
                    if nb not in seen:
                        seen.add(nb)
                        stack.append(nb)
            out.append([owner[start]] + sorted(group))
        return out

