function mergeProfiles(accounts: string[][]): string[][] {
  const parent = new Map<string, string>(), owner = new Map<string, string>();
  const find = (x: string): string => {
    while (parent.get(x) !== x) {
      const up = parent.get(parent.get(x)!)!;
      parent.set(x, up); // path halving
      x = up;
    }
    return x;
  };
  for (const [name, ...emails] of accounts) {
    for (const e of emails) {
      if (!parent.has(e)) parent.set(e, e);
      owner.set(e, name);
      const a = find(emails[0]), b = find(e);
      if (a !== b) parent.set(b, a);
    }
  }
  const groups = new Map<string, string[]>();
  for (const e of parent.keys()) {
    const root = find(e);
    if (!groups.has(root)) groups.set(root, []);
    groups.get(root)!.push(e);
  }
  const out: string[][] = [];
  for (const [root, emails] of groups) out.push([owner.get(root)!, ...emails.sort()]);
  return out;
}

