class Solution:
    def mergeProfiles(self, accounts: List[List[str]]) -> List[List[str]]:
        parent, owner = {}, {}

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]  # path halving
                x = parent[x]
            return x

        for name, *emails in accounts:
            for e in emails:
                parent.setdefault(e, e)
                owner[e] = name
                a, b = find(emails[0]), find(e)
                if a != b:
                    parent[b] = a
        groups = defaultdict(list)
        for e in parent:
            groups[find(e)].append(e)
        return [[owner[root]] + sorted(emails) for root, emails in groups.items()]

